<?php
use App\Models\Ticket;
if(!empty($filters['hierarchy'])) {
    $index=array_column($tickets,null,'id'); $childrenByParent=[]; $roots=[];
    foreach($tickets as $row) { if($row['parent_id']&&isset($index[$row['parent_id']])) $childrenByParent[$row['parent_id']][]=$row; else $roots[]=$row; }
    $ordered=[]; $visited=[];
    $visit=function(array $row,int $depth) use(&$visit,&$ordered,&$visited,$childrenByParent): void { if(isset($visited[$row['id']])) return; $visited[$row['id']]=true; $row['_depth']=$depth; $ordered[]=$row; foreach($childrenByParent[$row['id']]??[] as $child) $visit($child,$depth+1); };
    foreach($roots as $rootRow) $visit($rootRow,0);
    foreach($tickets as $remaining) if(!isset($visited[$remaining['id']])) $visit($remaining,0);
    $tickets=$ordered;
}
$group=$filters['group']??''; $grouped=[];
foreach($tickets as $ticket) { $g=match($group){'team'=>$ticket['team_name']??'Sans équipe','assignee'=>$ticket['assignee_name']??'Non assigné','priority'=>Ticket::PRIORITIES[$ticket['priority']],'type'=>Ticket::TYPES[$ticket['type']],'parent'=>$ticket['parent_id']?'Parent #'.$ticket['parent_id']:'Sans parent','labels'=>implode(', ',$ticket['labels_array'])?:'Sans étiquette',default=>''}; $grouped[$g][]=$ticket; }
?>
<form method="post" action="/bulk" id="bulk-form" class="bulk-bar" hidden><?= csrf() ?><span><strong data-selected-count>0</strong> sélectionné(s)</span><select name="field" aria-label="Champ à modifier"><option value="status">État</option><option value="priority">Priorité</option><option value="assignee_id">Personne assignée (identifiant)</option><option value="flagged">Blocage (0 ou 1)</option></select><input name="value" required placeholder="done, high, 1…" aria-label="Nouvelle valeur"><button class="button primary small-button" data-confirm="Appliquer cette modification à tous les tickets sélectionnés ?">Appliquer</button></form>
<div class="table-panel"><table class="ticket-table"><thead><tr><th class="checkbox-cell"><input type="checkbox" data-select-all aria-label="Sélectionner tous les tickets affichés"></th><th data-column="type">Type</th><th data-column="key">Clé</th><?php foreach(['title'=>'Résumé','assignee'=>'Personne assignée','team'=>'Équipe','priority'=>'Priorité','status'=>'État','due'=>'Échéance','estimated_hours'=>'Temps estimé (h)'] as $key=>$label): ?><th data-column="<?= e($key) ?>"><a href="<?= e(query_url('/'.$section,$baseQuery,['sort'=>$key,'direction'=>($filters['sort']??'')===$key&&($filters['direction']??'asc')==='asc'?'desc':'asc'])) ?>"><?= e($label) ?> <?= icon('down') ?></a></th><?php endforeach; ?><th data-column="labels">Étiquettes</th><th data-column="created">Création</th><th></th></tr></thead><tbody>
<?php foreach($grouped as $groupLabel=>$rows): if($groupLabel): ?><tr class="table-group"><td colspan="14"><?= e($groupLabel) ?><span><?= count($rows) ?></span></td></tr><?php endif; foreach($rows as $t): ?>
<tr data-ticket-id="<?= (int)$t['id'] ?>" data-version="<?= (int)$t['version'] ?>" data-parent="<?= (int)($t['parent_id']??0) ?>" data-depth="<?= (int)($t['_depth']??0) ?>" data-priority="<?= e($t['priority']) ?>" data-status="<?= e($t['status']) ?>" data-type="<?= e($t['type']) ?>" data-flagged="<?= (int)$t['flagged'] ?>">
<td class="checkbox-cell"><input type="checkbox" name="ids[]" value="<?= (int)$t['id'] ?>" form="bulk-form" data-select-ticket aria-label="Sélectionner <?= e($t['key']) ?>"></td><td data-column="type"><span class="type-icon type-<?= e($t['type']) ?>" title="<?= e(Ticket::TYPES[$t['type']]) ?>"><?= ['task'=>'✓','story'=>'▮','bug'=>'•','subtask'=>'⊡','epic'=>'ϟ'][$t['type']] ?></span></td><td data-column="key"><a class="ticket-key" href="<?= e(ticket_url((int)$t['id'])) ?>"><?= e($t['key']) ?></a></td><td class="title-cell" data-column="title"><?php if(!empty($filters['hierarchy'])&&!empty($childrenByParent[$t['id']])): ?><button class="tiny-button" data-toggle-children="<?= (int)$t['id'] ?>" aria-expanded="true" aria-label="Afficher ou masquer les tickets enfants">⌄</button><?php endif; ?><?php if(!empty($filters['hierarchy'])&&$t['parent_id']): ?><span class="hierarchy-indent">↳</span><?php endif; ?><a href="<?= e(ticket_url((int)$t['id'])) ?>"><?= e($t['title']) ?></a><?php if($t['flagged']): ?><span class="blocked-flag" title="Bloqué"><?= icon('flag') ?></span><?php endif; ?><button class="inline-edit" data-edit-field="title" data-value="<?= e($t['title']) ?>" aria-label="Modifier le résumé">✎</button></td><td data-column="assignee"><select class="cell-select" data-quick-field="assignee_id" aria-label="Personne assignée pour <?= e($t['key']) ?>"><option value="">Non assigné</option><?php foreach($members as $m): ?><option value="<?= (int)$m['id'] ?>" <?= $t['assignee_id']===$m['id']?'selected':'' ?>><?= e($m['name']) ?></option><?php endforeach; ?></select></td><td data-column="team"><?= e($t['team_name']??'Sans équipe') ?></td><td data-column="priority"><select class="cell-select priority-<?= e($t['priority']) ?>" data-quick-field="priority" aria-label="Priorité pour <?= e($t['key']) ?>"><?php foreach(Ticket::PRIORITIES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $t['priority']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></td><td data-column="status"><select class="status-select status-<?= e($t['status']) ?>" data-quick-field="status" aria-label="État pour <?= e($t['key']) ?>"><?php foreach(Ticket::STATUSES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $t['status']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></td><td data-column="due"><input class="cell-date" type="date" data-quick-field="due_date" value="<?= e($t['due_date']) ?>" aria-label="Échéance pour <?= e($t['key']) ?>"></td><td data-column="estimated_hours"><input class="cell-hours" inputmode="decimal" data-quick-field="estimated_hours" value="<?= e($t['estimated_hours']) ?>" maxlength="9" placeholder="—" aria-label="Temps estimé en heures pour <?= e($t['key']) ?>"></td><td data-column="labels"><?php foreach($t['labels_array'] as $label): ?><span class="label-tag"><?= e($label) ?></span><?php endforeach; ?></td><td data-column="created" class="muted"><?= e(substr($t['created_at'],0,10)) ?></td><td><a class="icon-button" href="<?= e(ticket_url((int)$t['id'])) ?>" aria-label="Ouvrir <?= e($t['key']) ?>"><?= icon('more') ?></a></td></tr>
<?php endforeach; endforeach; ?></tbody></table><?php if(!$tickets): ?><div class="empty-state"><?= icon('search') ?><h3>Aucun ticket sur cet horizon.</h3><p>Essayez d’autres filtres, ou créez le premier ticket.</p></div><?php endif; ?><div class="table-footer"><button class="text-button" data-open="ticket-dialog"><?= icon('plus') ?>Créer un ticket</button><span><?= min($count,($page-1)*$limit+1) ?>–<?= min($count,$page*$limit) ?> sur <?= $count ?></span><div><?php if($page>1): ?><a class="button subtle small-button" href="<?= e(query_url('/'.$section,$baseQuery,['page'=>$page-1])) ?>">Précédent</a><?php endif; if($page*$limit<$count): ?><a class="button subtle small-button" href="<?= e(query_url('/'.$section,$baseQuery,['page'=>$page+1])) ?>">Suivant</a><?php endif; ?></div></div></div>
